/* ============================================
   CreativeHub Design System
   ============================================ */

:root {
  --primary: #F02D00;
  --primary-hover: #d12600;
  --fg: #171717;
  --bg: #FFFFFF;
  --surface: #F6F6F6;
  --surface-2: #EEEEEE;
  --border: #E2E2E2;
  --muted: #6B6B6B;
  --muted-light: #9A9A9A;
  --accent-teal: #00C2A0;
  --accent-green: #2DD36F;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-xl: 20px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 14px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.10);
  --transition: 0.22s ease;
  --container: 1280px;
  --header-h: 64px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: "Inter", "DM Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--fg);
  background: var(--bg);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; }
ul, ol { margin: 0; padding: 0; list-style: none; }

/* Typography */
.h1 { font-size: clamp(2rem, 4vw + 0.5rem, 3.2rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
.h2 { font-size: clamp(1.5rem, 2.5vw + 0.5rem, 2.2rem); font-weight: 700; line-height: 1.15; letter-spacing: -0.01em; }
.h3 { font-size: clamp(1.15rem, 1.5vw + 0.4rem, 1.45rem); font-weight: 700; line-height: 1.25; }
.h4 { font-size: 1.05rem; font-weight: 700; line-height: 1.3; }
.text-sm { font-size: 0.92rem; }
.text-xs { font-size: 0.82rem; }
.text-muted { color: var(--muted); }

/* Layout */
.container { width: 100%; max-width: var(--container); margin: 0 auto; padding: 0 24px; }
.section { padding: 56px 0; }
@media (max-width: 640px) { .section { padding: 40px 0; } }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 10px 18px; border-radius: var(--radius-md); border: none; font-weight: 600; font-size: 0.95rem;
  transition: transform var(--transition), box-shadow var(--transition), background var(--transition);
}
.btn:hover { transform: translateY(-1px); }
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-hover); box-shadow: 0 6px 18px rgba(240,45,0,0.25); }
.btn-outline { background: transparent; color: var(--fg); border: 1.5px solid var(--border); }
.btn-outline:hover { border-color: var(--fg); }
.btn-dark { background: var(--fg); color: #fff; }
.btn-dark:hover { background: #2a2a2a; }
.btn-ghost { background: transparent; color: var(--muted); }
.btn-ghost:hover { color: var(--fg); }

/* Badges */
.badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; letter-spacing: 0.02em;
}
.badge-primary { background: var(--primary); color: #fff; }
.badge-sale { background: #FFF0ED; color: var(--primary); }
.badge-best { background: #FFF8E1; color: #B78900; }
.badge-free { background: #E8FDF6; color: #007A5E; }

/* Cards */
.card {
  background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius-lg);
  overflow: hidden; transition: box-shadow var(--transition), transform var(--transition);
}
.card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.card-media { position: relative; aspect-ratio: 16/10; background: var(--surface-2); overflow: hidden; }
.card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform var(--transition); }
.card:hover .card-media img { transform: scale(1.03); }
.card-body { padding: 14px 16px 16px; }
.card-title { font-weight: 700; font-size: 0.98rem; line-height: 1.3; margin: 0 0 6px; }
.card-meta { font-size: 0.85rem; color: var(--muted); }

/* Carousel */
.carousel-wrap { position: relative; }
.carousel-track { display: flex; gap: 16px; overflow-x: auto; scroll-behavior: smooth; scroll-snap-type: x mandatory; padding-bottom: 8px; }
.carousel-track::-webkit-scrollbar { height: 6px; }
.carousel-track::-webkit-scrollbar-thumb { background: var(--border); border-radius: 999px; }
.carousel-item { flex: 0 0 auto; scroll-snap-align: start; }
.carousel-arrow {
  position: absolute; top: 50%; transform: translateY(-50%); z-index: 2;
  width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--border); background: var(--bg);
  display: grid; place-items: center; box-shadow: var(--shadow-sm); transition: background var(--transition), border-color var(--transition);
}
.carousel-arrow:hover { background: var(--surface); border-color: var(--fg); }
.carousel-arrow.prev { left: -12px; }
.carousel-arrow.next { right: -12px; }
@media (max-width: 640px) {
  .carousel-arrow { width: 34px; height: 34px; }
  .carousel-arrow.prev { left: 4px; }
  .carousel-arrow.next { right: 4px; }
}

/* Header */
.site-header {
  position: sticky; top: 0; z-index: 100; background: rgba(255,255,255,0.92); backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--border);
}
.header-inner { display: flex; align-items: center; justify-content: space-between; height: var(--header-h); gap: 16px; }
.logo { font-weight: 900; font-size: 1.35rem; letter-spacing: -0.03em; display: flex; align-items: center; gap: 8px; }
.logo-mark { width: 28px; height: 28px; background: var(--primary); border-radius: 6px; display: grid; place-items: center; color: #fff; font-size: 0.85rem; }
.nav { display: flex; align-items: center; gap: 22px; }
.nav a { font-weight: 600; font-size: 0.92rem; color: var(--fg); opacity: 0.85; transition: opacity var(--transition); }
.nav a:hover { opacity: 1; }
.header-actions { display: flex; align-items: center; gap: 10px; }
.search-btn { width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--border); background: var(--bg); display: grid; place-items: center; }
.mobile-menu-btn { display: none; }
@media (max-width: 860px) {
  .nav { display: none; }
  .mobile-menu-btn { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 8px; border: 1px solid var(--border); background: var(--bg); }
}

/* Promo banner */
.promo-banner { background: var(--fg); color: #fff; font-size: 0.9rem; position: relative; }
.promo-banner .container { display: flex; align-items: center; justify-content: center; gap: 10px; padding-top: 10px; padding-bottom: 10px; }
.promo-banner .close { position: absolute; right: 16px; top: 50%; transform: translateY(-50%); background: transparent; border: none; color: #fff; opacity: 0.7; font-size: 1.1rem; }
.promo-banner .close:hover { opacity: 1; }
.countdown { font-weight: 700; font-variant-numeric: tabular-nums; }
@media (max-width: 640px) { .promo-banner .container { flex-wrap: wrap; text-align: center; } }

/* Footer */
.site-footer { background: var(--fg); color: #fff; padding: 56px 0 28px; }
.footer-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 28px; }
.footer-col h4 { font-size: 0.82rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; margin: 0 0 12px; opacity: 0.9; }
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a { font-size: 0.88rem; opacity: 0.7; transition: opacity var(--transition); }
.footer-col ul li a:hover { opacity: 1; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.08); margin-top: 36px; padding-top: 24px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.footer-bottom p { margin: 0; font-size: 0.82rem; opacity: 0.6; }
.footer-apps { display: flex; gap: 10px; }
.footer-apps a { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border: 1px solid rgba(255,255,255,0.15); border-radius: 8px; font-size: 0.8rem; opacity: 0.8; transition: opacity var(--transition), border-color var(--transition); }
.footer-apps a:hover { opacity: 1; border-color: rgba(255,255,255,0.35); }
@media (max-width: 980px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 640px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col h4 { cursor: pointer; display: flex; align-items: center; justify-content: space-between; }
  .footer-col h4::after { content: "+"; font-size: 1rem; }
  .footer-col.open h4::after { content: "−"; }
  .footer-col ul { display: none; }
  .footer-col.open ul { display: block; }
}

/* Plus page utilities */
.pricing-card {
  background: var(--bg); border: 2px solid var(--border); border-radius: var(--radius-xl); padding: 28px;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.pricing-card.active { border-color: var(--primary); box-shadow: 0 8px 28px rgba(240,45,0,0.10); }
.pricing-toggle { display: inline-flex; background: var(--surface); border-radius: 999px; padding: 4px; }
.pricing-toggle button { padding: 8px 18px; border-radius: 999px; border: none; background: transparent; font-weight: 700; font-size: 0.9rem; color: var(--muted); }
.pricing-toggle button.active { background: var(--fg); color: #fff; }

/* FAQ */
.faq-item { border-bottom: 1px solid var(--border); }
.faq-q {
  width: 100%; text-align: left; background: transparent; border: none; padding: 18px 0;
  font-weight: 700; font-size: 1.05rem; display: flex; align-items: center; justify-content: space-between; cursor: pointer;
}
.faq-q::after { content: "+"; font-size: 1.2rem; color: var(--muted); }
.faq-item.open .faq-q::after { content: "−"; }
.faq-a { max-height: 0; overflow: hidden; transition: max-height var(--transition), padding var(--transition); }
.faq-item.open .faq-a { max-height: 400px; padding-bottom: 18px; }

/* Login */
.login-wrap { min-height: 100vh; display: grid; grid-template-columns: 1fr 1fr; }
.login-visual { background: linear-gradient(135deg, #171717 0%, #2a2a2a 100%); color: #fff; display: flex; flex-direction: column; justify-content: flex-end; padding: 48px; position: relative; overflow: hidden; }
.login-visual::before { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 30% 20%, rgba(240,45,0,0.25), transparent 55%), radial-gradient(circle at 80% 80%, rgba(0,194,160,0.18), transparent 50%); }
.login-visual > * { position: relative; z-index: 1; }
.login-form-area { display: flex; align-items: center; justify-content: center; padding: 48px 24px; }
.login-box { width: 100%; max-width: 420px; }
.social-btn { width: 100%; padding: 12px; border-radius: var(--radius-md); border: 1.5px solid var(--border); background: var(--bg); font-weight: 600; font-size: 0.95rem; display: flex; align-items: center; justify-content: center; gap: 10px; margin-bottom: 10px; transition: border-color var(--transition), background var(--transition); }
.social-btn:hover { background: var(--surface); border-color: var(--fg); }
.divider { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 0.85rem; margin: 18px 0; }
.divider::before, .divider::after { content: ""; flex: 1; height: 1px; background: var(--border); }
.field { margin-bottom: 14px; }
.field label { display: block; font-size: 0.85rem; font-weight: 600; margin-bottom: 6px; }
.field input {
  width: 100%; padding: 12px 14px; border-radius: var(--radius-md); border: 1.5px solid var(--border); background: var(--bg); font-size: 0.95rem; outline: none; transition: border-color var(--transition), box-shadow var(--transition);
}
.field input:focus { border-color: var(--fg); box-shadow: 0 0 0 3px rgba(23,23,23,0.06); }
.password-wrap { position: relative; }
.password-wrap input { padding-right: 44px; }
.password-wrap .toggle { position: absolute; right: 10px; top: 50%; transform: translateY(-50%); background: none; border: none; color: var(--muted); font-size: 1rem; }
@media (max-width: 860px) { .login-wrap { grid-template-columns: 1fr; } .login-visual { display: none; } }

/* Courses page */
.courses-layout { display: grid; grid-template-columns: 240px 1fr; gap: 32px; }
.sidebar h3 { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.1em; color: var(--muted); margin: 24px 0 10px; }
.sidebar h3:first-child { margin-top: 0; }
.sidebar a { display: block; padding: 6px 0; font-size: 0.92rem; color: var(--fg); opacity: 0.8; transition: opacity var(--transition), color var(--transition); }
.sidebar a:hover, .sidebar a.active { opacity: 1; color: var(--primary); }
.course-grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
@media (max-width: 1100px) { .course-grid-4 { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 860px) { .courses-layout { grid-template-columns: 1fr; } .course-grid-4 { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 480px) { .course-grid-4 { grid-template-columns: 1fr; } }

/* Projects masonry */
.masonry { column-count: 4; column-gap: 18px; }
.masonry-item { break-inside: avoid; margin-bottom: 18px; border-radius: var(--radius-lg); overflow: hidden; background: var(--bg); border: 1px solid var(--border); }
.masonry-item img { width: 100%; display: block; }
.masonry-meta { padding: 10px 12px; }
@media (max-width: 1100px) { .masonry { column-count: 3; } }
@media (max-width: 768px) { .masonry { column-count: 2; } }
@media (max-width: 480px) { .masonry { column-count: 1; } }

/* Filter bar */
.filter-bar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 22px; }
.filter-bar select {
  padding: 8px 28px 8px 12px; border-radius: var(--radius-md); border: 1.5px solid var(--border); background: var(--bg); font-size: 0.9rem; appearance: none;
  background-image: url("data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1l5 5 5-5' stroke='%236B6B6B' stroke-width='1.5' fill='none' fill-rule='evenodd'/%3E%3C/svg%3E");
  background-repeat: no-repeat; background-position: right 10px center;
}

/* Hero */
.hero { background: linear-gradient(180deg, #fafafa 0%, #fff 100%); padding: 48px 0 56px; }
.hero-card {
  background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius-xl); overflow: hidden;
  display: grid; grid-template-columns: 1.1fr 1fr; align-items: center;
}
.hero-content { padding: 36px 40px; }
.hero-visual { background: var(--surface-2); min-height: 320px; position: relative; overflow: hidden; }
.hero-visual img { width: 100%; height: 100%; object-fit: cover; position: absolute; inset: 0; }
@media (max-width: 860px) {
  .hero-card { grid-template-columns: 1fr; }
  .hero-visual { min-height: 220px; order: -1; }
}

/* Section header */
.section-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 22px; }
.section-header h2 { margin: 0; }

/* Value props */
.value-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.value-card { background: var(--surface); border-radius: var(--radius-lg); padding: 22px; }
.value-card h4 { margin: 10px 0 6px; }
.value-card p { margin: 0; font-size: 0.9rem; color: var(--muted); }
.value-icon { width: 40px; height: 40px; border-radius: 10px; background: var(--bg); border: 1px solid var(--border); display: grid; place-items: center; font-size: 1.1rem; }
@media (max-width: 980px) { .value-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 520px) { .value-grid { grid-template-columns: 1fr; } }

/* Utility */
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.text-center { text-align: center; }
.mt-2 { margin-top: 8px; }
.mt-3 { margin-top: 12px; }
.mt-4 { margin-top: 16px; }
.mt-6 { margin-top: 24px; }
.mb-1 { margin-bottom: 4px; }
.mb-2 { margin-bottom: 8px; }
.mb-3 { margin-bottom: 12px; }
.flex { display: flex; }
.items-center { align-items: center; }
.gap-2 { gap: 8px; }
.gap-3 { gap: 12px; }
.justify-between { justify-content: space-between; }
